<script setup lang="ts">
import { computed,ref,watch,nextTick,onMounted,onBeforeUnmount,onDeactivated } from 'vue';
import { Plus, Network, Route, Server, Settings2, ArrowRight, Minus, Maximize2, Search, Download, Link2, X } from 'lucide-vue-next';
import {requestLeaveEditors} from './editorGuard';
import {type TopologyRouteState} from './navigationState';
import {displayPreferences as display} from './displayPreferences';
import NetworkDetails from './NetworkDetails.vue';import {networksForRoom,networkRoomLabel,networkRoomIds} from './networkScope';import LinkQuickEditor from './LinkQuickEditor.vue';
import NetworkLayerEditor from './NetworkLayerEditor.vue';
import DiagramExport from './DiagramExport.vue';
import NetworkQuickPanel from './NetworkQuickPanel.vue';
import {arrangeWithELK} from './elkLayout';
import {layersOf,layerOf} from './networkLayers';
import {projectTopology} from './topologyProjection';
import ActionMenu from './ActionMenu.vue';
import DeviceQuickActions from './DeviceQuickActions.vue';
import EditorPage from './EditorPage.vue';import {networkPath,canParentNetwork} from './networkTree';import Modal from './Modal.vue';import TopologyGraph from './TopologyGraph.vue';
import { request,networkPurposes,roleNames,download } from './model';
import type { State,Device,NetworkSegment,DeviceLink } from './model';
const props=defineProps<{state:State;projectId:string;networkId?:string}>();
const emit=defineEmits<{saved:[state:State];locate:[device:Device];editDevice:[device:Device];createDevice:[];editing:[title:string];initialize:[];'update:networkId':[id:string];navigation:[value:{path:{id:string;name:string}[];busy:boolean;filters?:TopologyRouteState}]}>();
const networkId=computed({get:()=>props.networkId||'',set:(id:string)=>emit('update:networkId',id)});
const showUnassigned=ref(true),searchOnly=ref(false);
const roomId=ref(''),query=ref(''),linkStatus=ref(''),zoom=ref(100),mode=ref('graph');
const diagram=ref<{fit:()=>void;actual:()=>void;zoomBy:(delta:number)=>void;revealNetwork:(id:string)=>void;preserveView:()=>void}>();
const toolsOpen=ref(false),maximized=ref(false);
function fitGraph(){nextTick(()=>diagram.value?.fit())}
function closeFullscreen(e:KeyboardEvent){if(e.key==='Escape'&&!document.querySelector('dialog[open]'))maximized.value=false}
onMounted(()=>window.addEventListener('keydown',closeFullscreen));onBeforeUnmount(()=>window.removeEventListener('keydown',closeFullscreen));onDeactivated(()=>maximized.value=false);
const quickBusy=ref(false),arranging=ref(false);
const networkPreview=ref<NetworkSegment>(),networkDetailsOpen=ref(false);
const quickTargetID=ref(''),layerTargetID=ref(''),showEmptyLayers=ref(false),createdNetworkID=ref('');
const quickTarget=computed(()=>networks.value.find(n=>n.id===(quickMode.value==='network'?quickTargetID.value:quickTargetID.value||networkId.value)));
const layerNetwork=computed(()=>networks.value.find(n=>n.id===(layerTargetID.value||networkId.value)));
const quickMode=ref<''|'network'|'members'|'links'>(''),quickInitial=ref<NetworkSegment>();
function quickNetwork(n?:NetworkSegment,parentId=''){if(busy.value||quickBusy.value||!requestLeaveEditors())return;quickTargetID.value=n?.parentId||parentId;toolsOpen.value=true;quickInitial.value=n;quickMode.value='network';error.value=''}
function openQuick(mode:'members'|'links',id=networkId.value){if(!id||busy.value||quickBusy.value||!requestLeaveEditors())return;quickTargetID.value=id;quickMode.value=mode;toolsOpen.value=true}
function toggleTools(){if(!requestLeaveEditors())return;if(toolsOpen.value)closeQuick();else toolsOpen.value=true}
function closeQuick(){networkPreview.value=undefined;quickMode.value='';quickBusy.value=false;toolsOpen.value=false}
async function createdNetwork(id:string){quickBusy.value=false;showUnassigned.value=true;createdNetworkID.value=id;closeQuick();await nextTick();diagram.value?.revealNetwork(id)}
function editNetworkId(id:string){const n=networks.value.find(n=>n.id===id);if(n)quickNetwork(n)}
function editLayers(id=networkId.value){if(!id||!requestLeaveEditors())return;layerTargetID.value=id;modal.value='layers';toolsOpen.value=false}
function deleteNetwork(n:NetworkSegment){if(busy.value||quickBusy.value||!requestLeaveEditors())return;networkForm.value=JSON.parse(JSON.stringify(n));deleteReturn.value='';closeQuick();modal.value='deleteNetwork'}
function advancedNetwork(n:NetworkSegment){if(!requestLeaveEditors())return;networkPreview.value=undefined;networkForm.value=JSON.parse(JSON.stringify(n));quickMode.value='';modal.value='network'}
const presentation=ref('auto');
const grouped=computed(()=>presentation.value!=='detail');
const graphDevices=computed(()=>matchingDevices.value);
const displayNodeCount=computed(()=>projectTopology(graphDevices.value,props.state.models,scope.value,props.state.networks,visibleLinks.value,grouped.value,new Set()).nodes.length);
const moveTarget=ref('');
const inspectorOpen=ref(false),connectionGroup=ref<string[]>([]);
const showInspector=computed(()=>display.details&&!!(networkDetailsOpen.value&&currentNetwork.value||selectedDevice.value||selectedLink.value||connectionGroup.value.length||inspectorOpen.value));
function toggleInspector(){if(!requestLeaveEditors())return;closeQuick();if(showInspector.value){display.details=false;networkPreview.value=undefined}else{display.details=true;inspectorOpen.value=true}}
const deleteReturn=ref('');
const selectedDevice=ref(''),selectedLink=ref(''),modal=ref(''),busy=ref(false),error=ref(''),message=ref(''),memberQuery=ref('');
watch(showInspector,()=>diagram.value?.preserveView(),{flush:'pre'});
const rooms=computed(()=>props.state.sites.filter(s=>s.projectId===props.projectId));
const roomOf=(d:Device)=>props.state.modules.find(m=>m.id===d.moduleId)?.siteId||'';
const projectDevices=computed(()=>props.state.devices.filter(d=>rooms.value.some(r=>r.id===roomOf(d))));
const networks=computed(()=>props.state.networks.filter(n=>n.projectId===props.projectId));
const links=computed(()=>props.state.links.filter(l=>l.projectId===props.projectId));
watch(networks,value=>{if(!value.length)presentation.value='detail'},{immediate:true});
const currentNetwork=computed(()=>networks.value.find(n=>n.id===networkId.value));

const navigationPath=computed(()=>[] as {id:string;name:string}[]);
const scope=computed(()=>{const list=networksForRoom(props.state,networks.value,roomId.value);if(networkPreview.value?.parentId){const ids=new Set([...list.map(n=>n.id),...networkPath(networks.value,networkPreview.value.parentId).map(n=>n.id)]);return networks.value.filter(n=>ids.has(n.id))}return list});
const scopeIDs=computed(()=>new Set(scope.value.map(n=>n.id)));
const children=computed(()=>networks.value.filter(n=>(n.parentId||'')===networkId.value));
const isEditor=computed(()=>['network','deviceNetwork'].includes(modal.value));
const eligibleParents=computed(()=>networks.value.filter(n=>canParentNetwork(networks.value,networkForm.value.id,n.id)));
const unassignedIDs=computed(()=>new Set(unassignedDevices.value.map(d=>d.id)));
const matchingLinks=computed(()=>links.value.filter(l=>!linkStatus.value||l.status===linkStatus.value));
const unassignedDevices=computed(()=>projectDevices.value.filter(d=>!networks.value.some(n=>n.deviceIds.includes(d.id))));
const scopedDevices=computed(()=>projectDevices.value.filter(d=>(showUnassigned.value||networks.value.some(n=>n.deviceIds.includes(d.id)))&&(!roomId.value||roomOf(d)===roomId.value)));
const directMatches=computed(()=>scopedDevices.value.filter(d=>!query.value||[d.name,d.assetTag,d.ip].join(' ').toLowerCase().includes(query.value.toLowerCase())));
const matchingDevices=computed(()=>{if(!query.value||searchOnly.value)return directMatches.value;const ids=new Set(directMatches.value.map(d=>d.id)),visible=new Set(ids);for(const l of matchingLinks.value){if(ids.has(l.sourceId))visible.add(l.targetId);if(ids.has(l.targetId))visible.add(l.sourceId)}return scopedDevices.value.filter(d=>visible.has(d.id))});
const visibleIds=computed(()=>new Set(matchingDevices.value.map(d=>d.id)));
const visibleLinks=computed(()=>matchingLinks.value.filter(l=>visibleIds.value.has(l.sourceId)&&visibleIds.value.has(l.targetId)));
const boundaryLinks=computed(()=>matchingLinks.value.filter(l=>visibleIds.value.has(l.sourceId)!==visibleIds.value.has(l.targetId)));
const graphLimit=300;
const exportScope=computed(()=>[
 props.state.projects.find(p=>p.id===props.projectId)?.name,
 '同图全部网络',
 roomId.value?rooms.value.find(r=>r.id===roomId.value)?.name:'全部机房',
 query.value?'搜索：'+query.value:'',linkStatus.value?'链路：'+(linkStatus.value==='pending'?'待确认':'已确认'):'',

 (grouped.value?matchingDevices.value.length:graphDevices.value.length)+' 台设备',
 boundaryLinks.value.length?'另有'+boundaryLinks.value.length+'条范围外连接未显示':''
].filter(Boolean).join(' · '));
const device=computed(()=>props.state.devices.find(d=>d.id===selectedDevice.value));
const link=computed(()=>links.value.find(l=>l.id===selectedLink.value));
const deviceNetworks=(id:string)=>networks.value.filter(n=>n.deviceIds.includes(id));
const deviceLinks=(id:string)=>links.value.filter(l=>l.sourceId===id||l.targetId===id);
const deviceName=(id:string)=>props.state.devices.find(d=>d.id===id)?.name||'设备不存在';
const rackLocation=(d:Device)=>{const m=props.state.modules.find(m=>m.id===d.moduleId),room=props.state.sites.find(s=>s.id===m?.siteId),r=props.state.racks.find(r=>r.id===d.rackId);return `${room?.name} / ${m?.name} / ${r?`${r.name} · U${d.startU}`:'待上架'}`};
const blankNetwork=():NetworkSegment=>({id:'',projectId:props.projectId,parentId:networkId.value,name:'',purpose:'business',vlan:0,cidr:'',gateway:'',color:'#497cda',deviceIds:[],note:''});
const blankLink=():DeviceLink=>({id:'',projectId:props.projectId,sourceId:selectedDevice.value||'',targetId:'',sourcePort:'',targetPort:'',networkIds:networkId.value?[networkId.value]:[],kind:'physical',medium:'',speedGbps:0,status:'pending',origin:'manual',note:''});
const editorRevision=ref(props.state.revision),editorConflict=ref(false);
const networkForm=ref(blankNetwork()),linkForm=ref(blankLink());
const advancedRoom=computed({get:()=>networkForm.value.roomScope==='project'?'__project':networkForm.value.siteId||'',set:(value:string)=>{networkForm.value.roomScope=value==='__project'?'project':'';networkForm.value.siteId=value==='__project'?'':value}});
const memberPage=ref(1),linkPage=ref(1);
const pageLinks=computed(()=>visibleLinks.value.slice((linkPage.value-1)*50,linkPage.value*50));
watch(()=>visibleLinks.value.length,total=>linkPage.value=Math.min(linkPage.value,Math.max(1,Math.ceil(total/50))));
watch([networkId,query,linkStatus,roomId],()=>linkPage.value=1);
const members=computed(()=>projectDevices.value.filter(d=>[d.name,d.assetTag,props.state.models.find(m=>m.id===d.modelId)?.name].join(' ').toLowerCase().includes(memberQuery.value.toLowerCase())));
const pageMembers=computed(()=>members.value.slice((memberPage.value-1)*50,memberPage.value*50));
watch(memberQuery,()=>memberPage.value=1);
function selectMatchingMembers(){networkForm.value.deviceIds=[...new Set([...networkForm.value.deviceIds,...members.value.map(d=>d.id)])]}
function clearMatchingMembers(){const ids=new Set(members.value.map(d=>d.id));networkForm.value.deviceIds=networkForm.value.deviceIds.filter(id=>!ids.has(id))}
const inference=ref<{revision:number;networkId:string;links:DeviceLink[]}|null>(null);
const routeFilters=computed<TopologyRouteState>(()=>({query:query.value,status:linkStatus.value,filterRoom:roomId.value,device:selectedDevice.value,link:selectedLink.value,unassigned:showUnassigned.value,presentation:presentation.value==='auto'?'':presentation.value,mode:mode.value==='graph'?'':mode.value,searchOnly:searchOnly.value}));
watch([navigationPath,busy,quickBusy,arranging,routeFilters],()=>emit('navigation',{path:navigationPath.value.map(n=>({id:n.id,name:n.name})),busy:busy.value||quickBusy.value||arranging.value,filters:routeFilters.value}),{immediate:true});
async function restoreFilters(route:TopologyRouteState){query.value=route.query||'';linkStatus.value=['pending','confirmed'].includes(route.status||'')?route.status!:'';roomId.value=rooms.value.some(r=>r.id===route.filterRoom)?route.filterRoom!:'';showUnassigned.value=route.unassigned!==false;searchOnly.value=!!route.searchOnly;await nextTick();presentation.value=route.presentation==='detail'?'detail':networks.value.length?'auto':'detail';mode.value=route.mode==='links'?'links':'graph';selectedDevice.value=projectDevices.value.some(d=>d.id===route.device)?route.device!:'';selectedLink.value=links.value.some(l=>l.id===route.link)?route.link!:'';if(selectedDevice.value||selectedLink.value){display.details=true;inspectorOpen.value=true}else if(currentNetwork.value){networkDetailsOpen.value=true;display.details=true}}
watch(()=>props.projectId,()=>{membershipUndo.value=undefined;showUnassigned.value=true;connectionGroup.value=[];roomId.value='';query.value='';selectedDevice.value='';selectedLink.value='';networkDetailsOpen.value=false;networkPreview.value=undefined;modal.value='';quickMode.value='';inference.value=null});
watch(roomId,()=>{networkDetailsOpen.value=false;networkPreview.value=undefined;createdNetworkID.value='';connectionGroup.value=[];inspectorOpen.value=false;quickMode.value='' ;selectedDevice.value='';selectedLink.value='';inference.value=null});
watch(query,()=>inference.value=null);
watch(modal,()=>{editorRevision.value=props.state.revision;editorConflict.value=false;memberPage.value=1;if(modal.value)toolsOpen.value=false;error.value='';memberQuery.value='';emit('editing',isEditor.value?(modal.value==='network'?'编辑网络':modal.value==='deviceNetwork'?'设备网络设置':modal.value==='layers'?'网络分层设置':'编辑链路'):'')});
async function write(path:string,method:string,data:object){if(busy.value||quickBusy.value||isEditor.value&&editorConflict.value)return false;busy.value=true;error.value='';message.value='';try{emit('saved',await request<State>(path,method,{revision:isEditor.value?editorRevision.value:props.state.revision,...data}));message.value='网络配置已保存';return true}catch(e){error.value=(e as Error).message;if((e as {status?:number}).status===409){editorConflict.value=isEditor.value;try{emit('saved',await request<State>('/state'));inference.value=null}catch{}if(editorConflict.value)error.value='数据已被其他操作修改。请复制需要保留的内容，再关闭编辑并载入最新数据；旧表单不能直接覆盖。'}return false}finally{busy.value=false}}
function editLink(l?:DeviceLink){if(!requestLeaveEditors())return;linkForm.value=l?{...l,networkIds:[...l.networkIds]}:blankLink();modal.value='link'}
const duplicateNetwork=computed(()=>networks.value.find(n=>n.id!==networkForm.value.id&&n.name.trim().toLowerCase()===networkForm.value.name.trim().toLowerCase()));
async function saveNetwork(){const n=networkForm.value;if(duplicateNetwork.value){error.value=`项目中已有「${n.name.trim()}」，请打开已有网络或换一个名称。`;return}if(await write('/networks'+(n.id?'/'+n.id:''),n.id?'PUT':'POST',{network:n}))modal.value=''}
async function remove(){const network=modal.value==='deleteNetwork';const id=network?networkForm.value.id:linkForm.value.id;if(await write((network?'/networks/':'/links/')+id,'DELETE',network?{detach:true,liftChildren:true}:{})){if(network){showUnassigned.value=true;selectedDevice.value='';if(networkId.value===id)networkId.value=networkForm.value.parentId||''}selectedLink.value='';modal.value=''}}
type MembershipSnapshot={networks:NetworkSegment[];links:DeviceLink[]};
const membershipUndo=ref<{before:MembershipSnapshot;after:MembershipSnapshot;revision:number;undone:boolean}>();
function memberSnapshot():MembershipSnapshot{return JSON.parse(JSON.stringify({networks:networks.value,links:links.value}))}
async function moveMember(deviceId:string,sourceId:string,targetId:string){await moveMembers([deviceId],sourceId,targetId,!sourceId)}
async function moveMembers(ids:string[],sourceId:string,targetId:string,copy:boolean){
 if(!ids.length||sourceId===targetId)return;
 const before=memberSnapshot();
 if(await write('/network-members','POST',{deviceIds:ids,sourceId:copy?'':sourceId,targetId,mode:copy||!sourceId?'add':'move'})){
  await nextTick();membershipUndo.value={before,after:memberSnapshot(),revision:props.state.revision,undone:false};
  message.value=`已${copy?'加入':'移入'}目标网络 · ${ids.length}台设备；可撤销本次归属变更`;selectedDevice.value='';selectedLink.value='';connectionGroup.value=[]
 }
}
async function restoreMembership(){
 const action=membershipUndo.value;if(!action||action.revision!==props.state.revision)return;
 const snapshot=action.undone?action.after:action.before;
 if(await write('/topology/restore-membership','POST',{projectId:props.projectId,...snapshot})){
  await nextTick();membershipUndo.value={...action,revision:props.state.revision,undone:!action.undone};message.value=action.undone?'已重做网络归属变更':'已撤销网络归属变更，设备归属与链路标签已恢复'
 }
}
async function savePositions(networkId:string,positions:{deviceId:string;position:{x:number;y:number}}[]){if(await write('/topology/device-positions','POST',{projectId:props.projectId,networkId,positions}))message.value=`已保存 ${positions.length} 台设备的图位置`}
async function connectDevices(sourceId:string,targetId:string){
 if(sourceId===targetId)return;const existing=links.value.find(l=>l.sourceId===sourceId&&l.targetId===targetId||l.sourceId===targetId&&l.targetId===sourceId);
 if(existing){selectLink(existing.id);message.value='两台设备已有连接，已打开连接详情';return}
 const link={...blankLink(),sourceId,targetId,kind:'logical',status:'pending',networkIds:networks.value.filter(n=>n.deviceIds.includes(sourceId)&&n.deviceIds.includes(targetId)).map(n=>n.id),note:'拖动创建，实际连线与端口待确认'};
 if(await write('/links','POST',{link})){message.value='已建立待确认连接；端口等参数可在连接详情中编辑';await nextTick();const saved=links.value.find(l=>l.sourceId===sourceId&&l.targetId===targetId);if(saved)selectLink(saved.id)}
}
async function removeMember(deviceId:string,sourceId=networkId.value){
 const network=networks.value.find(n=>n.id===sourceId&&n.deviceIds.includes(deviceId));if(!network)return;
 const before=memberSnapshot();
 if(await write('/network-members','POST',{deviceId,sourceId,targetId:'',mode:'remove'})){
  await nextTick();membershipUndo.value={before,after:memberSnapshot(),revision:props.state.revision,undone:false};
  showUnassigned.value=true;message.value=`已从「${network.name}」移出，保留设备、其他网络归属与实际连接；可撤销`
 }
}
async function applyDeviceSetting(kind:'reset'|'remove'|'move'){
 const d=device.value;if(!d)return;
 if(kind==='reset')await resetPosition(d);
 else if(kind==='remove')await removeMember(d.id);
 else await moveMember(d.id,currentNetwork.value?.deviceIds.includes(d.id)?networkId.value:scope.value.find(n=>n.deviceIds.includes(d.id))?.id||'',moveTarget.value);
 if(!error.value)modal.value='';
}
async function savePosition(deviceId:string,id:string,position:{x:number;y:number}){if(await write(id?'/networks/'+id+'/position':'/devices/'+deviceId+'/topology-position','POST',{deviceId,position}))message.value='设备图位置已保存'}
async function resetPosition(d:Device){const n=scope.value.find(n=>n.deviceIds.includes(d.id));await write(n?'/networks/'+n.id+'/position':'/devices/'+d.id+'/topology-position','POST',{deviceId:d.id,position:null})}
function enterNetwork(id:string,afterSave=false){if(busy.value||quickBusy.value||arranging.value||!afterSave&&!requestLeaveEditors())return false;networkPreview.value=undefined;const target=networks.value.find(n=>n.id===id);if(target&&!scope.value.some(n=>n.id===id)){roomId.value=networkRoomIds(props.state,target)[0]||''}networkId.value=id;moveTarget.value='';closeQuick();selectedDevice.value='';selectedLink.value='';connectionGroup.value=[];networkDetailsOpen.value=!!id;display.details=true;return true}
function locateNetwork(id:string,afterSave=false){if(enterNetwork(id,afterSave)&&id)nextTick(()=>diagram.value?.revealNetwork(id))}
async function assignLayer(networkId:string,deviceIds:string[],layerId:string){if(await write('/networks/'+networkId+'/layer-members','POST',{deviceIds,layerId}))message.value='设备排列层已调整'}
function selectConnectionGroup(ids:string[]){connectionGroup.value=ids;selectedDevice.value='';selectedLink.value='';inspectorOpen.value=true;display.details=true}
function navigate(id:string,root=false){if(busy.value||quickBusy.value||arranging.value)return;modal.value='';networkPreview.value=undefined;networkDetailsOpen.value=false;quickMode.value='';selectedDevice.value='';selectedLink.value='';connectionGroup.value=[];inference.value=null;error.value='';message.value='';if(root){toolsOpen.value=false;showUnassigned.value=true;roomId.value='';query.value='';linkStatus.value='';mode.value='graph';presentation.value=networks.value.length?'auto':'detail';searchOnly.value=false;zoom.value=100}locateNetwork(id)}
function shortcut(action:string){if(busy.value||quickBusy.value||arranging.value)return;if(action==='escape'){if(!requestLeaveEditors())return;modal.value='';quickMode.value='';toolsOpen.value=false;selectedDevice.value='';selectedLink.value='';return}if(isEditor.value)return;if(action==='link'&&projectDevices.value.length>=2)editLink();if(action==='fit')fitGraph();if(action==='new')quickNetwork();if(action==='edit'){if(device.value)emit('editDevice',device.value);else if(link.value)editLink(link.value);else if(currentNetwork.value)quickNetwork(currentNetwork.value)}}
defineExpose({navigate,restoreFilters,shortcut});
async function suggest(){if(!networkId.value)return;modal.value='suggest';busy.value=true;inference.value=null;try{const result=await request<{revision:number;links:DeviceLink[]}>('/topology/preview','POST',{revision:props.state.revision,networkId:networkId.value});inference.value={...result,networkId:networkId.value}}catch(e){error.value=(e as Error).message;if((e as {status?:number}).status===409){try{emit('saved',await request<State>('/state'))}catch{}}}finally{busy.value=false}}
async function commitSuggestion(){if(!inference.value||inference.value.revision!==props.state.revision||inference.value.networkId!==networkId.value){error.value='数据或分区已变化，请关闭后重新推演';return}if(await write('/topology/commit','POST',{networkId:inference.value.networkId}))modal.value=''}
function selectDevice(id:string){if(!requestLeaveEditors())return;networkDetailsOpen.value=false;closeQuick();connectionGroup.value=[];display.details=true;moveTarget.value='';selectedDevice.value=id;selectedLink.value=''}
function selectLink(id:string){if(!requestLeaveEditors())return;networkDetailsOpen.value=false;closeQuick();connectionGroup.value=[];display.details=true;selectedLink.value=id;selectedDevice.value=''}
async function autoLayout(){if(busy.value||quickBusy.value||arranging.value)return;arranging.value=true;error.value='';message.value='正在整理分层与连接…';const revision=props.state.revision,project=props.projectId;try{const groups=await arrangeWithELK(props.state,graphDevices.value,scope.value);if(revision!==props.state.revision||project!==props.projectId){error.value='数据已变化，请重新自动排列';return}if(await write('/topology/arrange','POST',{projectId:props.projectId,groups})){message.value='已整理分层和网络间距，成员与连接保持不变';await nextTick();fitGraph()}}catch(e){error.value=(e as Error).message}finally{arranging.value=false}}

async function positionNetwork(id:string,position:{x:number;y:number}){await write('/networks/'+id+'/layout-position','POST',{position});if(!error.value)message.value='网络位置已保存'}
function exportTopology(){download('项目网络拓扑.json',JSON.stringify({version:1,project:props.state.projects.find(p=>p.id===props.projectId),devices:projectDevices.value,networks:networks.value,links:links.value},null,2))}
</script>
<template>
 <section :class="['topology-workspace','canvas-first',{'canvas-maximized':maximized}]" ><div v-show="!isEditor" class="topology-workbench" :class="{'inspector-visible':showInspector}">
  <aside v-show="toolsOpen" class="topology-navigation panel" aria-label="网络列表面板"><div class="panel-heading"><h2>网络列表</h2><button class="icon-button" aria-label="收起网络面板" @click="requestLeaveEditors()&&closeQuick()"><X :size="16"/></button></div>
  <div v-if="!projectDevices.length" class="topology-start"><Network :size="30"/><div><h2>导入设备，建立拓扑</h2><p>一张清单带入设备、网络与连接。</p></div><button class="primary" @click="emit('initialize')">导入初始化</button></div><div class="topology-actions"><ActionMenu label="拓扑更多操作"><button :disabled="!networkId||busy" @click="suggest">按型号推演</button><button aria-label="导出项目拓扑JSON" @click="exportTopology">导出项目拓扑JSON</button></ActionMenu></div>
  <NetworkQuickPanel v-if="quickMode" :key="quickMode+(quickMode==='network'?quickInitial?.id||'new:'+quickTargetID:quickTarget?.id||'')" :mode="quickMode" :state="state" :project-id="projectId" :network="quickTarget" :initial="quickMode==='network'?quickInitial:undefined" :site-id="roomId|| (rooms.length===1?rooms[0].id:'')" :parent-id="quickTargetID" @preview="networkPreview=$event" @busy="quickBusy=$event" @close="closeQuick" @saved="(next,text)=>{emit('saved',next);message=text}" @advanced="advancedNetwork" @open="id=>{quickBusy=false;locateNetwork(id,true)}" @created="createdNetwork" @remove="deleteNetwork"/>


  <section class="panel network-partitions"><div class="panel-heading"><h2>当前图网络 <small>{{scope.length}}</small></h2><div><button class="text-button" :aria-expanded="display.networks" @click="display.networks=!display.networks">{{display.networks?'收起网络列表':'展开网络列表'}}</button><button v-if="currentNetwork" class="text-button" @click="quickNetwork(currentNetwork)">编辑当前网络</button></div></div><div class="network-chips"><div v-for="n in scope" :key="n.id" class="network-chip-group" :data-network-drop="n.id" :data-network-card="n.id" :draggable="false"  :style="{'--network-color':n.color}"><button @click="locateNetwork(n.id)" :aria-label="`定位网络 ${n.name}`"><i :style="{background:n.color}"></i><span><strong>{{n.name}}</strong><small>{{networkPath(networks,n.id).map(p=>p.name).join(' / ')}} · {{n.deviceIds.length}} 台设备</small></span><ArrowRight :size="13"/></button><button class="icon-button" :aria-label="`编辑网络 ${n.name}`" @click="quickNetwork(n)"><Settings2 :size="14"/></button></div></div><p v-if="!children.length" class="panel-note">{{currentNetwork?'选择网络后可添加设备或修改放置位置。':'新建网络后直接在图中添加设备并建立连接。'}}</p></section>
  <div v-if="currentNetwork" class="member-actions"><button class="secondary" :disabled="busy||quickBusy||currentNetwork.deviceIds.length<2" @click="openQuick('links')">批量连线</button></div>

<div class="topology-secondary-tools"><label>链路状态<select v-model="linkStatus" aria-label="链路确认状态"><option value="">全部确认状态</option><option value="pending">待确认</option><option value="confirmed">已确认</option></select></label></div><details class="compact-help"><summary>项目统计</summary><div class="network-summary"><div><Network :size="19"/><strong>{{networks.length}}</strong><span>网络</span></div><div><Server :size="19"/><strong>{{projectDevices.length}}</strong><span>台账设备</span></div><div><Link2 :size="19"/><strong>{{links.length}}</strong><span>设备链路</span></div><div><Route :size="19"/><strong>{{links.filter(l=>l.status==='pending').length}}</strong><span>待确认关系</span></div></div></details></aside>
  <div v-if="message" class="canvas-notice" role="status">{{message}}<button v-if="membershipUndo&&membershipUndo.revision===state.revision" class="secondary" :disabled="busy" @click="restoreMembership">{{membershipUndo.undone?'重做网络归属变更':'撤销网络归属变更'}}</button><button class="icon-button" aria-label="关闭拓扑提示" @click="message=''">×</button></div><div v-if="error&&!modal" class="error-banner" role="alert">{{error}}</div>
  <section class="panel topology-panel"><div class="topology-command-header"><div class="topology-context-row"><label class="topology-room-scope">机房<select v-model="roomId" aria-label="拓扑机房范围"><option value="">项目全部机房（含跨机房连接）</option><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option></select></label><div class="topology-context-title"><h2>{{rooms.find(r=>r.id===roomId)?.name||'项目'}}网络图</h2><span>{{matchingDevices.length}} 台设备 · {{scope.length}} 个网络 · {{visibleLinks.length}} 条设备连接</span></div><div class="search-box"><Search :size="16"/><input v-model="query" aria-label="搜索拓扑设备" placeholder="搜索设备名称、编号或IP…"/></div><button v-if="query||roomId||linkStatus" class="text-button" @click="query='';roomId='';linkStatus=''">清除筛选</button></div><div class="topology-primary-toolbar"><div class="topology-command-group" role="group" aria-label="网络管理"><span class="command-group-label">网络</span><button class="secondary" aria-label="新建网络" aria-keyshortcuts="Alt+n" title="新建网络（Alt+N）" @click="quickNetwork()"><Plus :size="14"/>新建网络</button><button v-if="currentNetwork" class="secondary" @click="quickNetwork(currentNetwork)">修改网络</button><button class="secondary" aria-label="网络列表" :aria-expanded="toolsOpen" @click="toggleTools">网络列表</button><button v-if="currentNetwork" class="text-button danger-text" @click="deleteNetwork(currentNetwork)">删除网络</button></div><div class="topology-command-group" role="group" aria-label="设备与连接"><span class="command-group-label">设备与连接</span><button v-if="currentNetwork" class="primary" @click="openQuick('members')">添加现有设备</button><button class="secondary" :disabled="projectDevices.length<2" aria-keyshortcuts="Alt+l" title="新增链路（Alt+L）" @click="editLink()"><Plus :size="14"/>新增链路</button><button class="secondary" @click="emit('createDevice')">新建设备</button></div><div class="topology-command-group view-command-group" role="group" aria-label="查看工具"><span class="command-group-label">查看</span><button v-if="unassignedDevices.length" class="secondary unassigned-toggle" :aria-pressed="showUnassigned" @click="showUnassigned=!showUnassigned">未分配设备（{{unassignedDevices.length}}）</button><DiagramExport :title="(currentNetwork?.name||'项目')+'网络拓扑图'" :scope="exportScope" selector=".topology-content .topology-canvas svg" :disabled="busy||mode!=='graph'||!matchingDevices.length||displayNodeCount>graphLimit"/><button class="secondary" :aria-expanded="showInspector" @click="toggleInspector">{{showInspector?'收起详情':'显示详情'}}</button><button class="icon-button" :aria-label="maximized?'退出画布最大化':'最大化画布'" :title="maximized?'退出画布最大化':'最大化画布'" @click="maximized=!maximized"><Maximize2 :size="17"/></button></div></div></div>
   <div class="network-selection-bar"><span>当前操作：<strong>{{currentNetwork?.name||'未选择网络'}}</strong></span><span v-if="currentNetwork">{{networkPath(networks,currentNetwork.id).map(n=>n.name).join(' / ')}} · {{networkRoomLabel(state,currentNetwork)}}</span><span v-else>点击网络标题选择；同机房网络始终在一张图内</span><button v-if="currentNetwork" class="text-button" @click="enterNetwork('')">取消网络选择</button></div>
   <p v-if="createdNetworkID&&networks.some(n=>n.id===createdNetworkID)" class="new-network-notice" role="status">已创建「{{networks.find(n=>n.id===createdNetworkID)?.name}}」 · 上级：{{networks.find(n=>n.id===networks.find(c=>c.id===createdNetworkID)?.parentId)?.name||'项目根网络'}}。<button class="text-button" @click="locateNetwork(createdNetworkID);createdNetworkID=''">定位新网络</button><button class="text-button" @click="openQuick('members',createdNetworkID)">为新网络添加设备</button></p>
   <div class="canvas-controls" role="toolbar" aria-label="画布视图控制"><select v-if="mode==='graph'" v-model="presentation" aria-label="拓扑展示方式"><option value="auto">合并同类</option><option value="detail">全部展开</option></select><div class="zoom-controls"><button aria-label="缩小拓扑" :disabled="zoom<=10" @click="diagram?.zoomBy(-10)"><Minus :size="13"/></button><button aria-label="实际比例100%" @click="diagram?.actual()">{{zoom}}%</button><button aria-label="放大拓扑" :disabled="zoom>=400" @click="diagram?.zoomBy(10)"><Plus :size="13"/></button><button aria-label="重置拓扑缩放" @click="fitGraph">总览</button></div><ActionMenu label="画布操作"><button class="text-button" :disabled="busy||arranging||!graphDevices.length" @click="autoLayout">自动排列</button><button v-if="currentNetwork" @click="editLayers()">分层设置</button><button v-if="currentNetwork" :aria-pressed="showEmptyLayers" @click="showEmptyLayers=!showEmptyLayers">{{showEmptyLayers?'隐藏空显示层':'显示空显示层'}}</button><button @click="mode=mode==='graph'?'links':'graph'">{{mode==='graph'?'链路清单':'拓扑图'}}</button><button v-if="!networkId&&unassignedDevices.length" :aria-pressed="showUnassigned" @click="showUnassigned=!showUnassigned">{{showUnassigned?'隐藏':'显示'}}未分配设备（{{unassignedDevices.length}}）</button></ActionMenu></div>
   <p v-if="boundaryLinks.length" class="panel-note">当前筛选隐藏了 {{boundaryLinks.length}} 条连接到范围外设备的链路。清除搜索或切换“项目全部机房 / 项目拓扑”可查看完整关系。</p>
   <p v-if="showUnassigned&&unassignedDevices.length&&!query" class="panel-note">{{currentNetwork?'同一机房的网络与设备保持可见。选中网络只确定操作对象；添加设备可拖入或批量选择。':roomId?'已显示所选机房的设备。未分配设备可拖入网络框，也可批量添加。':'已显示项目全部设备。未分配设备可拖入网络框，也可在创建网络后批量添加。'}}</p><p v-if="query" class="panel-note">命中 {{directMatches.length}} 台设备{{searchOnly?'':'，同时显示相邻设备与连接'}}。<label class="checkbox-label"><input v-model="searchOnly" type="checkbox"/>只显示匹配设备</label></p><div class="topology-main" :class="{'inspector-visible':showInspector,'navigation-visible':toolsOpen}"><div class="topology-content"><template v-if="mode==='graph'"><div v-if="displayNodeCount>graphLimit" class="empty-state"><Network :size="34"/><h3>当前有 {{matchingDevices.length}} 台设备</h3><p>单张图最多展示 {{graphLimit}} 张卡片，请使用合并同类，或按机房、搜索缩小范围。链路清单与导出保留全部数据。</p></div><div v-else-if="!networkPreview&&!matchingDevices.length&&(!scope.length||!!query)" class="empty-state"><Network :size="34"/><h3>{{projectDevices.length?'当前筛选没有匹配设备':'等待设备入库'}}</h3><p>{{projectDevices.length?'可调整筛选、添加网络成员，或打开“显示未分配设备”。':'先在设备台账中新增或导入服务器、交换机等设备。'}}</p><div class="empty-actions"><button class="secondary" @click="emit('createDevice')">新增设备</button><button class="secondary" @click="emit('initialize')">导入设备清单</button></div></div><TopologyGraph @add-members="id=>openQuick('members',id)" @network="enterNetwork" @edit-network="editNetworkId" @create-network="id=>quickNetwork(undefined,id)" :preview="networkPreview" :highlight-network="createdNetworkID" @layers="editLayers" @update:zoom="zoom=$event" @layer="assignLayer" :show-layers="true" :show-empty-layers="showEmptyLayers" :merge="grouped" :search-matches="query?directMatches.map(d=>d.id):undefined" @notice="message=$event" @connect="connectDevices" @positions="savePositions" @members="moveMembers" @link-group="selectConnectionGroup" @network-position="positionNetwork" ref="diagram" v-else :state="state" :devices="graphDevices" :networks="scope" :links="visibleLinks" :busy="busy||quickBusy||arranging" :network-id="networkId" :selected-device="selectedDevice" :selected-link="selectedLink" :zoom="zoom" @device="selectDevice" @link="selectLink" @position="savePosition"/></template>
    <div v-else class="table-scroll link-table"><table><thead><tr><th>设备 / 端口 A</th><th>设备 / 端口 B</th><th>网络 / 速率</th><th>类型 / 确认</th><th>操作</th></tr></thead><tbody><tr v-for="l in pageLinks" :key="l.id"><td>{{deviceName(l.sourceId)}}<small>{{l.sourcePort||'端口待录入'}}</small></td><td>{{deviceName(l.targetId)}}<small>{{l.targetPort||'端口待录入'}}</small></td><td>{{networks.filter(n=>l.networkIds.includes(n.id)).map(n=>n.name).join(' / ')||'网络未指定'}}<small>{{l.speedGbps?l.speedGbps+' Gbps':'速率待录入'}}</small></td><td>{{l.kind==='physical'?'物理':'逻辑'}}<small>{{l.status==='confirmed'?'已确认':'待确认'}} · {{l.origin==='inferred'?'推演':'手工'}}</small></td><td><button class="text-button" :aria-label="`编辑链路 ${deviceName(l.sourceId)} 到 ${deviceName(l.targetId)}`" @click="editLink(l)">编辑</button></td></tr></tbody></table><div v-if="visibleLinks.length>50" class="list-pagination"><button class="secondary" :disabled="linkPage<=1" @click="linkPage--">上一页链路</button><span>{{linkPage}} / {{Math.ceil(visibleLinks.length/50)}} · 共 {{visibleLinks.length}} 条</span><button class="secondary" :disabled="linkPage*50>=visibleLinks.length" @click="linkPage++">下一页链路</button></div><div v-if="!visibleLinks.length" class="empty-state"><h3>暂无可见链路</h3><p>新增连接或调整筛选范围。</p></div></div>
   </div></div></section><aside v-if="showInspector" :inert="toolsOpen" class="topology-inspector" aria-label="拓扑对象详情"><div class="selection-heading"><span class="selection-type">{{device?'已选中 · 设备':networkDetailsOpen && currentNetwork?'已选中 · 网络':link?'已选中 · 链路':connectionGroup.length?'合并连接明细':'对象详情'}}</span><button v-if="device||link||connectionGroup.length" class="text-button" aria-label="取消拓扑选择" @click="selectedDevice='';selectedLink='';connectionGroup=[];inspectorOpen=true">取消选择</button><button class="icon-button" aria-label="收起拓扑详情" title="收起详情" @click="requestLeaveEditors()&&(display.details=false,networkPreview=undefined)"><X :size="16"/></button></div><NetworkDetails v-if="!isEditor&&networkDetailsOpen && currentNetwork&&!device&&!link" :key="currentNetwork.id+':'+toolsOpen" :state="state" :network="currentNetwork" :busy="busy||quickBusy" @saved="emit('saved',$event);message='网络已更新'" @busy="quickBusy=$event" @preview="networkPreview=$event" @members="openQuick('members',$event)" @create="quickNetwork(undefined,$event)" @edit="advancedNetwork" @layers="editLayers" @remove="deleteNetwork" @select="locateNetwork"/><template v-else-if="device"><div class="inspector-device-heading"><h3>{{device.name}}</h3><p class="mono">{{device.assetTag}}</p></div><dl class="device-facts"><div><dt>设备角色</dt><dd>{{roleNames[state.models.find(m=>m.id===device?.modelId)!.role]}}</dd></div><div><dt>机房位置</dt><dd>{{rackLocation(device)}}</dd></div><div><dt>台账 IP</dt><dd>{{device.ip||'未录入'}}<small>台账地址不等于各网络接口IP</small></dd></div><div><dt>所属网络</dt><dd><div v-for="n in deviceNetworks(device.id)" :key="n.id" class="inspector-network"><div class="inspector-network-heading"><strong><i class="network-dot" :style="{background:n.color}"></i><button class="text-button" :aria-label="'定位所属网络 '+n.name" @click="locateNetwork(n.id)">{{n.name}}</button></strong><button class="text-button" :disabled="busy||quickBusy" :aria-label="'从'+n.name+'移出设备'" title="只移除此网络归属，可撤销" @click="removeMember(device.id,n.id)">移出</button></div><small>VLAN {{n.vlan||'未指定'}} · {{n.cidr||'网段未录入'}}<br/>网关 {{n.gateway||'未录入'}}</small></div><span v-if="!deviceNetworks(device.id).length">未划分网络</span></dd></div></dl><label v-if="currentNetwork?.deviceIds.includes(device.id)" class="inspector-layer">当前网络的显示层<select :value="layerOf(currentNetwork,device.id,state.models.find(m=>m.id===device?.modelId)?.role||'server')" aria-label="选中设备排列层" :disabled="busy||quickBusy" @change="assignLayer(currentNetwork.id,[device.id],($event.target as HTMLSelectElement).value)"><option v-for="layer in layersOf(currentNetwork)" :key="layer.id" :value="layer.id">{{layer.name}}</option></select></label><div class="inspector-actions"><button class="secondary" @click="emit('locate',device)">在机房中定位 <ArrowRight :size="14"/></button><button class="primary" aria-keyshortcuts="Alt+e" title="编辑设备详情（Alt+E）" @click="emit('editDevice',device)">编辑设备详情</button><button class="secondary" @click="modal='deviceNetwork'">设备网络设置</button><button class="secondary" @click="editLink()">为此设备新增链路</button></div><DeviceQuickActions :state="state" :device="device" :disabled="busy||quickBusy" @saved="emit('saved',$event);message='设备机位已更新'" @busy="busy=$event"/><section class="inspector-connections" aria-label="设备直接连接"><h3>直接连接 · {{deviceLinks(device.id).length}}</h3><p v-if="!deviceLinks(device.id).length" class="muted small">暂无直接连接</p><div class="inspector-links"><button v-for="l in deviceLinks(device.id)" :key="l.id" class="neighbor-link" @click="selectLink(l.id)">{{deviceName(l.sourceId===device.id?l.targetId:l.sourceId)}}<small>{{l.kind==='physical'?'物理':'逻辑'}} · {{l.status==='confirmed'?'已确认':'待确认'}}</small></button></div></section></template>
   <template v-else-if="link"><h3>{{link.kind==='physical'?'物理链路':'逻辑链路'}}</h3><span :class="['status-badge',link.status==='confirmed'?'installed':'pending']">{{link.status==='confirmed'?'已确认':'待确认'}}</span><div class="inspector-link-actions"><button class="primary" @click="editLink(link)">编辑连接与确认状态</button><button class="secondary" :disabled="busy" @click="write('/links/'+link.id,'PUT',{link:{...link,status:link.status==='confirmed'?'pending':'confirmed'}})">{{link.status==='confirmed'?'改为待确认':'确认此链路'}}</button><button class="text-button danger-text" :disabled="busy" @click="linkForm={...link,networkIds:[...link.networkIds]};deleteReturn='';modal='deleteLink'">删除链路</button></div><dl><dt>端点 A</dt><dd><button class="text-button" @click="selectDevice(link.sourceId)">{{deviceName(link.sourceId)}}</button><small>{{link.sourcePort||'端口待录入'}}</small></dd><dt>端点 B</dt><dd><button class="text-button" @click="selectDevice(link.targetId)">{{deviceName(link.targetId)}}</button><small>{{link.targetPort||'端口待录入'}}</small></dd><dt>承载网络</dt><dd>{{networks.filter(n=>link?.networkIds.includes(n.id)).map(n=>n.name).join(' / ')||'未指定'}}</dd><dt>介质 / 速率</dt><dd>{{link.medium||'待录入'}} / {{link.speedGbps?link.speedGbps+' Gbps':'待录入'}}</dd><dt>来源</dt><dd>{{link.origin==='inferred'?'按型号推演':'手工录入'}}</dd><dt>备注</dt><dd>{{link.note||'—'}}</dd></dl></template>
   <template v-else-if="connectionGroup.length"><h3>{{connectionGroup.length}} 条真实连接</h3><button v-for="l in links.filter(l=>connectionGroup.includes(l.id))" :key="l.id" class="neighbor-link" @click="selectLink(l.id)">{{deviceName(l.sourceId)}} → {{deviceName(l.targetId)}}<small>{{l.kind==='physical'?'物理':'逻辑'}} · {{l.status==='confirmed'?'已确认':'待确认'}}</small></button></template><template v-else><Network :size="32"/><h3>选择设备或链路</h3><p>点击图中对象查看详情，拖动设备调整位置。</p><div class="graph-legend"><span><i></i>已确认物理链路</span><span><i class="dashed"></i>待确认链路</span><span><i class="dotted"></i>已确认逻辑链路</span></div><details class="compact-help"><summary>图例与显示规则</summary><p>多网络设备仅绘制一次，徽标列出所属网络。图形为台账，不代表实时流量或隔离已生效。</p></details></template>
   </aside>
  </div>
  <component :is="isEditor?EditorPage:Modal" v-if="modal" :key="modal" :error="error" :draft="modal==='network'?networkForm:modal==='link'?linkForm:modal==='deviceNetwork'?moveTarget:undefined" :title="modal==='network'?(networkForm.id?'编辑网络':'新建网络'):modal==='link'?(linkForm.id?'编辑设备链路':'新增设备链路'):modal==='suggest'?'推演连接预览':modal==='deviceNetwork'?'设备网络设置':modal==='layers'?'排列层设置':modal==='deleteLink'?'删除设备链路':'删除网络配置'" wide :busy="busy||quickBusy||arranging" @close="requestLeaveEditors()&&(modal='')">
   <div v-if="error" class="error-banner" role="alert">{{error}}<button v-if="editorConflict" class="secondary" @click="requestLeaveEditors()&&(modal='')">关闭编辑并载入最新数据</button></div>
   <NetworkLayerEditor v-if="modal==='layers'&&layerNetwork" :state="state" :network="layerNetwork" @saved="emit('saved',$event)" @busy="busy=$event"/><form v-else-if="modal==='network'" @submit.prevent="saveNetwork"><div class="form-grid"><label>所属机房<select v-model="advancedRoom" aria-label="网络所属机房" :required="!networkForm.id"><option value="" :disabled="!networkForm.id">待指定机房</option><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option><option value="__project">跨机房（项目范围）</option></select></label><label class="span-two">放置位置<select v-model="networkForm.parentId" aria-label="放置位置"><option value="">机房最外层</option><option v-for="n in eligibleParents" :key="n.id" :value="n.id">{{networkPath(networks,n.id).map(p=>p.name).join(' / ')}}</option></select></label><label>网络名称<input :aria-invalid="!!duplicateNetwork" :aria-describedby="duplicateNetwork?'network-name-error':undefined" v-model="networkForm.name" required maxlength="80" placeholder="例如：业务网络"/><span v-if="duplicateNetwork" id="network-name-error" class="field-error">该名称已存在，请换名或编辑已有网络。</span></label><label>网络用途<select v-model="networkForm.purpose" aria-label="网络用途"><option v-for="(name,key) in networkPurposes" :key="key" :value="key">{{name}}</option></select></label><label>VLAN ID<input aria-label="VLAN ID" v-model.number="networkForm.vlan" type="number" min="0" max="4094" required/><small>0表示未指定；不同分区可使用相同VLAN编号。</small></label><label>网络颜色<input v-model="networkForm.color" type="color" aria-label="网络颜色"/></label><label>网段 CIDR<input v-model="networkForm.cidr" placeholder="例如：10.10.0.0/24，可留空" name="cidr" spellcheck="false" autocomplete="off"/></label><label>网关地址<input v-model="networkForm.gateway" placeholder="可留空，填写时必须属于网段" name="gateway" spellcheck="false" autocomplete="off"/></label></div><label class="full-label">备注<textarea v-model="networkForm.note" maxlength="2000" rows="2"/></label><div class="form-section-heading"><h3>成员设备 · 已选 {{networkForm.deviceIds.length}} 台</h3><input v-model="memberQuery" aria-label="搜索网络成员" placeholder="按名称、资产编号或型号搜索"/></div><div class="quick-selection"><button type="button" class="text-button" @click="selectMatchingMembers">全选匹配成员（{{members.length}}）</button><button type="button" class="text-button" @click="clearMatchingMembers">取消匹配成员</button></div><div class="network-members"><label v-for="d in pageMembers" :key="d.id" class="checkbox-label"><input v-model="networkForm.deviceIds" type="checkbox" :value="d.id" :aria-label="`网络成员 ${d.name}`"/><span>{{d.name}}<small>{{d.assetTag}} · {{state.modules.find(m=>m.id===d.moduleId)?.name}}</small></span></label><div v-if="members.length>50" class="list-pagination"><button type="button" class="secondary" :disabled="memberPage<=1" @click="memberPage--">上一页成员</button><span>{{memberPage}} / {{Math.ceil(members.length/50)}} · 共 {{members.length}} 台</span><button type="button" class="secondary" :disabled="memberPage*50>=members.length" @click="memberPage++">下一页成员</button></div><p v-if="!members.length" class="muted small">暂无匹配设备，请先入库或调整搜索。</p></div><details class="compact-help"><summary>操作帮助</summary><p>成员可以属于多个分区。移除成员前须先调整引用该分区的链路；配置只记录网络划分，不下发交换机配置。</p></details><div class="modal-actions"><button v-if="networkForm.id" type="button" class="text-button danger-text" @click="deleteReturn='network';modal='deleteNetwork'">删除此网络</button><span v-else></span><button class="primary" :disabled="busy">保存网络</button></div></form>
   <LinkQuickEditor v-else-if="modal==='link'" :state="state" :project-id="projectId" :network-id="networkId" :initial="linkForm" @busy="busy=$event" @saved="next=>{emit('saved',next);modal='';message='链路已保存'}" @remove="l=>{linkForm=l;deleteReturn='link';modal='deleteLink'}"/>
   <div v-else-if="modal==='deviceNetwork'&&device"><div class="form-section-heading"><h3>{{device.name}}</h3><span class="muted small">{{device.assetTag}}</span></div><div class="network-members"><p v-for="n in deviceNetworks(device.id)" :key="n.id">{{networkPath(networks,n.id).map(p=>p.name).join(' / ')}}</p></div><div class="form-grid"><label>移入子网络<select v-model="moveTarget" aria-label="设备目标子网络"><option value="">选择目标网络</option><option v-for="n in networks.filter(n=>n.id!==networkId)" :key="n.id" :value="n.id">{{networkPath(networks,n.id).map(p=>p.name).join(' / ')}}</option></select></label></div><div class="modal-actions"><button type="button" class="text-button" :disabled="busy" @click="applyDeviceSetting('reset')">恢复自动排列</button><button v-if="currentNetwork?.deviceIds.includes(device.id)" type="button" class="text-button danger-text" :disabled="busy" @click="applyDeviceSetting('remove')">从当前子网移出</button><button class="primary" :disabled="busy||!moveTarget" @click="applyDeviceSetting('move')">移动设备</button></div></div>
   <div v-else-if="modal==='suggest'"><div class="info-banner">仅在所选分区成员内，按核心 → 汇聚 → 接入 → 服务器层级推演；优先同模块，并跳过已有上联。生成待确认逻辑关系，不推断真实端口、冗余和速率。</div><div v-if="busy&&!inference" class="panel-note">正在计算候选关系…</div><template v-if="inference"><p class="inference-summary" role="status">{{inference.links.length}} 条候选连接 · 待确认逻辑关系</p><details class="compact-help"><summary>操作帮助</summary><p>预览不写入数据库。若没有上层设备，或成员已存在连接，将不会新增。</p></details><div class="preview-table"><table><thead><tr><th>上层设备</th><th>下层设备</th><th>状态</th></tr></thead><tbody><tr v-for="l in inference.links" :key="l.id"><td>{{deviceName(l.sourceId)}}</td><td>{{deviceName(l.targetId)}}</td><td>逻辑 · 待确认</td></tr></tbody></table></div></template><div class="modal-actions"><span class="muted small">人工检查后可编辑、确认或删除</span><button class="primary" :disabled="busy||!inference?.links.length" @click="commitSuggestion">记录待确认连接</button></div></div>
   <div v-else><p class="delete-message">确认删除{{modal==='deleteNetwork'?`网络「${networkForm.name}」`:`设备链路「${deviceName(linkForm.sourceId)} ↔ ${deviceName(linkForm.targetId)}」`}}？设备台账保留，删除操作记录审计。{{modal==='deleteNetwork'?'只删除此网络。保留设备和实际连接；直属子网络移到该网络原来的上一级，其他归属保留。失去全部网络归属的设备会显示在未分配区。':''}}</p><div class="modal-actions"><button class="secondary" @click="modal=deleteReturn">取消</button><button class="danger" :disabled="busy" @click="remove">{{modal==='deleteNetwork'?'确认删除网络配置':'确认删除链路'}}</button></div></div>
  </component>
 </section>
</template>
